          destRight[di + 1] += srcRight[i + 1] * g;
          destLeft[di + 2] += srcLeft[i + 2] * g;
          destRight[di + 2] += srcRight[i + 2] * g;
          destLeft[di + 3] += srcLeft[i + 3] * g;
          destRight[di + 3] += srcRight[i + 3] * g;
          i += 4; di += 4;
